//package com.company;
// Always comment out package when submitting.


import java.io.*;
import java.util.*;

public class Main {
    public static class Task {
        int mod = 1_000_000_007;
        public void solve(Scanner sc, PrintWriter pw) throws IOException {
            int n = sc.nextInt();
            long[][] dp0 = new long[n + 1][n + 1];
            long[][] dp1 = new long[n + 1][n + 1];
            for (int ij = 2 * n; ij >= 0; ij--) {
                for (int i = 0; i <= n; i++) {
                    int j = ij - i;
                    if (i < 0 || j < 0) continue;
                    if (j > i) continue;
                    if (i == n && j == n) continue;
                    if (i == j) {
                        dp0[i][j] = Math.max(1 + dp1[i + 1][j], dp0[i + 1][j]);
                    } else if ( i == n) {
                        dp0[i][j] = Math.max(1 + dp1[i][j + 1], dp0[i][j + 1]);
                    } else {
                        long v1 = (dp0[i + 1][j] + dp0[i][j + 1]) % mod;
                        long v2 = (1 + dp1[i + 1][j] + dp0[i][j + 1]) % mod;
                        long v3 = (1 + dp0[i + 1][j] + dp1[i][j + 1]) % mod;
                        dp0[i][j] = Math.max(v1, Math.max(v2, v3));
                    }
                    if (i == j) {
                        dp1[i][j] = dp0[i + 1][j];
                    } else if ( i == n) {
                        dp1[i][j] = dp0[i][j + 1];
                    } else {
                        long v1 = (dp0[i + 1][j] + dp0[i][j + 1]) % mod;
                        dp1[i][j] = v1;
                    }
                }
            }
            pw.println(dp0[0][0] % mod);

        }
    }

    // template, actual code is in class Task.
    static long TIME_START, TIME_END;

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
//        Scanner sc = new Scanner(new FileInputStream("Test.in"));
        PrintWriter pw = new PrintWriter(new BufferedOutputStream(System.out));
//        PrintWriter pw = new PrintWriter(new FileOutputStream("Test.out"));

        Runtime runtime = Runtime.getRuntime();
        long usedMemoryBefore = runtime.totalMemory() - runtime.freeMemory();
        TIME_START = System.currentTimeMillis();
        Task t = new Task();
        t.solve(sc, pw);
        TIME_END = System.currentTimeMillis();
        long usedMemoryAfter = runtime.totalMemory() - runtime.freeMemory();
        pw.close();
//        System.err.println("Memory increased: " + (usedMemoryAfter - usedMemoryBefore) / 1000000);
//        System.err.println("Time used: " + (TIME_END - TIME_START) + ".");
    }

    // Faster IO with BufferedReader wrapped with Scanner
    static class Scanner {
        StringTokenizer st;
        BufferedReader br;

        public Scanner(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        public Scanner(FileReader s) throws FileNotFoundException {
            br = new BufferedReader(s);
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens())
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public String nextLine() throws IOException {
            return br.readLine();
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        public boolean ready() throws IOException {
            return br.ready();
        }
    }
}
